// Five hundred utility diversions. Shuffle once so adjacent messages do not repeat a template.
const favourites=['Teaching the meters to use their inside voices…','Sorting bills into emotionally supportive piles…','Asking the hamsters to check their spreadsheets…','Convincing the backlog to form an orderly queue…','Putting the kettle on at the substation…','Counting every last suspicious kilowatt-hour…','Packing tiny lunches for the field crews…','Giving the water mains a pep talk…','Untangling a very ambitious extension cord…','Checking whether that pool is secretly a lake…','Handing out high-visibility vests to the numbers…','Asking February to explain itself…','Teaching the spreadsheets to share…','Finding the meter behind the suspicious shrub…','Reminding the invoices to use their manners…','Practising our very official clipboard walk…','Offering the validation rules a biscuit…','Making room for one more what-if…','Sending the estimated reads to finishing school…','Putting little wheels on the work orders…','Checking the storm’s appointment calendar…','Counting houses, then counting them again…','Giving the busy signal a short break…','Tucking the finished results into their folders…'];
const subjects=["the meters", "the invoices", "the kilowatt-hours", "the queues", "the calendars", "the thermostats", "the spreadsheets", "the work orders", "the service crews", "the water mains", "the timestamps", "the transformers", "the payment plans", "the circuit breakers", "the read schedules", "the decimal places", "the bills", "the valves", "the estimates", "the streetlights", "the due dates", "the utility poles", "the registers", "the billing cycles", "the pump stations", "the field notes", "the pie charts", "the receipts"];
const phrases=["Giving {s} a pep talk and a very small biscuit…", "Checking {s} have packed their lunch…", "Reminding {s} that this is a utility, not a talent show…", "Asking {s} to line up by height…", "Teaching {s} the official clipboard salute…", "Fitting {s} for high-visibility pyjamas…", "Making sure {s} have signed the birthday card…", "Settling a friendly argument between {s} and a stapler…", "Taking {s} on a supervised spreadsheet outing…", "Explaining daylight saving time to {s}. Again…", "Handing {s} their participation rosettes…", "Asking {s} to stop hiding behind the photocopier…", "Putting {s} in charge of the tiny biscuit budget…", "Helping {s} rehearse their indoor voices…", "Giving {s} a strictly unofficial gold star…", "Checking {s} for unauthorised jazz hands…", "Convincing {s} the progress bar is not a race…"];
const messages=[...favourites,...phrases.flatMap(p=>subjects.map(s=>p.replace('{s}',s)))];
let seed=20261005;for(let i=messages.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[messages[i],messages[j]]=[messages[j],messages[i]];}
export const LOAD_MESSAGES=Object.freeze(messages);
export const loadingMessage=(now=Date.now())=>LOAD_MESSAGES[Math.floor(now/6500)%LOAD_MESSAGES.length];
